// cordis-go placement runner: one process of a `revl run --placement`
// composition placed on the Go backend. Reads a spec JSON (argv[1]), consumes
// cross-process keys through emitter-generated proxies, loads its own cordis-go
// components, optionally serves its provided keys over a Unix socket, runs
// probes, and (unless a peer dies first) holds until SIGTERM/stdin-close, then
// tears down consumers-first.
//
// The proxies, the stub dispatch, the key->service table and the component
// loader are all GENERATED by backends/go/emit.py into the `emitted` package
// (per composition), so this runner carries no composition-specific knowledge:
// cordis-go services are static Go interfaces, so generality is codegen, not a
// runtime-generic proxy. This mirrors backends/rust/placement_runner/main.rs.
//
// Peer death is withdrawal (R2/R3, docs/interop-bridge.md): a monitor
// connection sees EOF when a provider dies; the runner disposes that key's
// proxy fiber, which withdraws the provision, and every dependent deactivates
// reactively — the same reactive path a local provider swap takes.
package main

import (
	stdctx "context"
	"encoding/json"
	"fmt"
	"io"
	"math"
	"net"
	"os"
	"os/signal"
	"sort"
	"strconv"
	"strings"
	"syscall"
	"time"

	stc "github.com/0xdenny218/stc-go"

	"revl.goplacement/bridge"
	"revl.goplacement/emitted"
	"revl.goplacement/estop"
)

type proxyInfo struct {
	Socket  string   `json:"socket"`
	Methods []string `json:"methods"`
	Service string   `json:"service"`
}

type serveInfo struct {
	Socket  string              `json:"socket"`
	Keys    []string            `json:"keys"`
	Methods map[string][]string `json:"methods"`
}

// exportedSurface is what this process serves: the keys other processes
// consume from it (`serve.keys`) and, per key, the operations its service
// declaration admits (`serve.methods`, the allowlist `placement.py` reads off
// the IR). The generated `RevlInvoke` resolves EVERY key the document's
// components provide, so without this check a raw call reached a key this
// process provides but does not export, and any key it holds a proxy for
// (issue #1599). A request outside the surface is refused with the py
// bridge's wording and never dispatched.
type exportedSurface struct {
	keys    map[string]bool
	methods map[string]map[string]bool
}

func newExportedSurface(s *serveInfo) exportedSurface {
	out := exportedSurface{keys: map[string]bool{}, methods: map[string]map[string]bool{}}
	for _, k := range s.Keys {
		out.keys[k] = true
	}
	for k, ops := range s.Methods {
		set := map[string]bool{}
		for _, op := range ops {
			set[op] = true
		}
		out.methods[k] = set
	}
	return out
}

// check returns the refusal for a request outside the surface, or nil. A key
// with no `methods` entry is left to the generated dispatch, which admits only
// the service's declared operations.
func (e exportedSurface) check(key, method string, declared []string) error {
	if !e.keys[key] {
		return fmt.Errorf("key '%s' is not exported by this process", key)
	}
	ops, listed := e.methods[key]
	if listed && !ops[method] {
		names := "(none)"
		if len(declared) > 0 {
			names = strings.Join(declared, ", ")
		}
		return fmt.Errorf("method '%s' is not exported for key '%s' (exported: %s)", method, key, names)
	}
	return nil
}

type probe struct {
	Key    string `json:"key"`
	Method string `json:"method"`
	// Typed JSON values (issue #1559): `placement._parse_probe` types each
	// argument by the operation's declared parameter type, so they pass
	// through to the dispatch unchanged. A `[]string` here decoded `41` as
	// the string "41", which an int64 parameter then read as 0.
	Args []json.RawMessage `json:"args"`
}

type placement struct {
	Component string  `json:"component"`
	Realm     *string `json:"realm"`
}

type spec struct {
	Name       string                     `json:"name"`
	Components []string                   `json:"components"`
	Config     map[string]json.RawMessage `json:"config"`
	Provides   []string                   `json:"provides"`
	Proxies    map[string]proxyInfo       `json:"proxies"`
	Probe      []probe                    `json:"probe"`
	Serve      *serveInfo                 `json:"serve"`
	// Placements (issue #1567): key -> the provisions this process makes of
	// it, each with the realm an `isolate` publishes it in ("" for the shared
	// realm). A served or probed key resolves through `resolveIn`.
	Placements map[string][]placement `json:"placements"`
	// Once (revl run --backend go --once) replaces the hold-until-stopped
	// loop with the boot -> LIFO teardown -> no-residue-proof -> exit
	// round-trip, the same driver contract the rust/java/wasm tiers run.
	Once bool `json:"once"`
	// EstopLatch (item 443, issue #122): the operator E-Stop latch the conductor
	// hands a honoring child in its spec (`src/revl/placement.py`). A sandboxed
	// child (item 411) need not inherit the conductor's environment, so the latch
	// travels in the spec and the runner publishes it to the ambient variable the
	// seams already read. Empty when the placement was never armed.
	EstopLatch string `json:"estopLatch"`
	// ProofOnStdin (issue #1621): the `--once` runner hands this process a
	// per-run token as the first line of stdin, and the four proof lines
	// (`UP`, `NO-RESIDUE`, `RESIDUE-LEFT`, `DOWN`) carry it, so a program's own
	// output cannot forge them. A flag here, never the token: the spec is a
	// file the program could read.
	ProofOnStdin bool `json:"proofOnStdin"`
}

// readProofToken reads the first line of stdin one byte at a time, so nothing
// past it is buffered away from the stop-on-EOF reader below. It runs before
// any component loads, so no host code has run yet, and the token lives only
// in main's locals: the emitted package cannot name it (issue #1621).
func readProofToken() string {
	var token []byte
	buf := make([]byte, 1)
	for {
		n, err := os.Stdin.Read(buf)
		if n == 1 {
			if buf[0] == '\n' {
				break
			}
			token = append(token, buf[0])
		}
		if err != nil {
			break
		}
	}
	return strings.TrimSpace(string(token))
}

type labeledFiber struct {
	label string
	fiber *stc.Fiber
}

// fatalLine composes the one line this process prints for a failure no
// load-path or probe-path funnel saw. It is the only place that spells the
// line, so the goroutine that runs main and the goroutine that answers a
// crossing cannot drift apart (issue #814).
func fatalLine(name string, fatal any) {
	fmt.Fprintln(os.Stderr, "["+name+"] FATAL "+bridge.ScrubText(fmt.Sprint(fatal)))
}

// fatalBoot ends a boot that cannot be honoured, as the rust runner's
// `fatal_boot` does (#2200): one scrubbed FATAL line on stderr, what did boot
// disposed last first, exit 1. Every boot-failure arm goes through here so the
// teardown they promise cannot drift apart (issues #2223, #2254). `os.Exit`,
// not a panic or a return, so the teardown in main never prints `DOWN` for a
// failed boot.
//
// `Dispose` only REQUESTS the teardown, so each one is awaited (bounded) or
// `os.Exit` would kill the process before any inverse replayed. A fiber that
// does not settle in time is reported as such, never as disposed. `Gone` also
// returns for a fiber that had already FAILED, which replays nothing, so the
// line names the state the fiber ended in. `log` is main's scrubbing
// printer, passed in because it is a closure over the process name.
func fatalBoot(name, message string, fibers []labeledFiber,
	log func(channel, subject, detail string)) {
	fatalLine(name, message)
	bootCtx, bootCancel := stdctx.WithTimeout(stdctx.Background(), teardownBound())
	for i := len(fibers) - 1; i >= 0; i-- {
		disposeAwaited(bootCtx, fibers[i], log)
	}
	bootCancel()
	os.Exit(1)
}

// defaultTeardownGrace is the conductor's default for REVL_TEARDOWN_GRACE:
// _TEARDOWN_GRACE in src/revl/placement.py, the single source. The conductor
// kills a child that has not said DOWN this long after it was asked to stop,
// so a runner that defaulted lower called a correct 5 to 30 second inverse a
// failed teardown (issue #2356).
const defaultTeardownGrace = 30 * time.Second

// teardownMargin is how long before the conductor's grace the runner gives up,
// so its FATAL line is always written before the conductor's kill can swallow
// it.
const teardownMargin = 2 * time.Second

// maxTeardownGrace is the most REVL_TEARDOWN_GRACE may ask for, in seconds
// (_TEARDOWN_GRACE_MAX in src/revl/placement.py); more is clamped, as the
// conductor clamps it.
const maxTeardownGrace = 86400

// teardownBound is the wait the teardown gives its disposes: the conductor's
// grace (REVL_TEARDOWN_GRACE seconds, the variable the stranded-teardown report
// tells a user to raise, when it is a positive finite number, else the
// conductor's default) less a margin, so the runner reports first. The margin
// never exceeds half the grace, which keeps a short grace usable.
func teardownBound() time.Duration {
	grace := defaultTeardownGrace
	if raw := os.Getenv("REVL_TEARDOWN_GRACE"); raw != "" {
		secs, err := strconv.ParseFloat(raw, 64)
		if err == nil && secs > 0 {
			grace = time.Duration(math.Min(secs, maxTeardownGrace) * float64(time.Second))
		}
	}
	margin := teardownMargin
	if grace/2 < margin {
		margin = grace / 2
	}
	return grace - margin
}

// disposeAwaited disposes one fiber and waits (bounded by ctx) for the
// teardown to settle, then logs what was confirmed: the inverses replayed, the
// state the fiber ended in (`Gone` also returns for a fiber that had already
// FAILED, which replays nothing), or that it did not settle in time. Shared by
// the boot-failure path and the normal teardown so the two cannot drift
// (issue #2336). It returns false only when the dispose did not settle in time:
// the inverses may still be pending, so the caller must not call the unwind
// complete (issue #2339).
func disposeAwaited(ctx stdctx.Context, lf labeledFiber,
	log func(channel, subject, detail string)) bool {
	lf.fiber.Dispose()
	if err := lf.fiber.Gone(ctx); err != nil {
		log("swap", lf.label, "dispose NOT confirmed: "+err.Error())
		return false
	}
	if state := lf.fiber.State(); state != stc.StateGone {
		log("swap", lf.label, "dispose -> ended "+state.String())
		return true
	}
	log("swap", lf.label, "dispose -> inverses replay (LIFO)")
	return true
}

// guard returns the deferred function that funnels a failure of the goroutine
// it is deferred in: one redacted line on stderr, then `os.Exit`, which runs NO
// teardown and so reaches no `DOWN` — the conductor's clean-teardown signal
// (E7). It is a no-op on a goroutine that returns normally.
//
// It exists because Go has no process-wide panic hook: `recover` covers only
// the goroutine that runs it, so main's defer cannot see a panic anywhere else.
// The runtime prints a panic it reaches the top of, VERBATIM, on stderr — and
// the panic value quotes whatever the failing frame held. A crossing's own
// goroutine needs no guard: `bridge.Serve` recovers its handler's panic into
// the error reply (issue #2481).
//
// The indirection is load-bearing: `recover` stops a panic only when the
// DEFERRED FUNCTION calls it directly, so the closure returned here — never a
// helper it calls — has to be the one that runs. Call sites spell it
// `defer guard(&name)()`; dropping the trailing `()` calls the guard while the
// goroutine is still healthy and recovers nothing.
//
// The label arrives BY POINTER because main registers its defer before the spec
// is parsed: the closure has to read the label when the FAILURE happens, not
// when the defer statement runs, or a panic after boot would still be labelled
// `proc` once the spec had named the placement. Same reason the java tier's
// handler reads a `volatile` field rather than a captured local.
func sortedOps(ops []string) []string {
	out := append([]string(nil), ops...)
	sort.Strings(out)
	return out
}

func guard(name *string) func() {
	return func() {
		if fatal := recover(); fatal != nil {
			fatalLine(*name, fatal)
			os.Exit(1)
		}
	}
}

func main() {
	// The uncaught-failure funnel (issue #814, the go half). The load path and
	// the probe path each funnel the failures they expect; anything else — a
	// config hook, a serve setup, an inverse during teardown — used to escape
	// as a PANIC, and the runtime prints a panic value plus a stack trace
	// straight to stderr, unfunnelled. The conductor merges that verbatim
	// (`placement.py::pump`), and the panic value quotes whatever the failing
	// frame held: the go tier has no second chance to redact it.
	//
	// One redacted line, non-zero exit: still loud, still machine-visible, no
	// longer an unanalysed crossing. `os.Exit`, not a re-panic, for the reason
	// the E-Stop watcher below exits: a process that died mid-boot must not
	// reach the teardown that prints `DOWN`, which is the conductor's
	// clean-teardown signal (E7). This defer is registered FIRST, so it runs
	// LAST: every other defer in main (the teardown's `cancel`) has already
	// run by the time it does. It covers THIS goroutine only — see `guard` —
	// and the other goroutines main starts carry their own.
	name := "proc"
	defer guard(&name)()
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "usage: revl_placement_runner <spec.json>")
		os.Exit(2)
	}
	raw, err := os.ReadFile(os.Args[1])
	if err != nil {
		// item 421 F5: these three lines run before any component has loaded,
		// but `bridge.ScrubText` is already live — the emitted package installs
		// the scrub in an `init`, so it is in force from the first statement of
		// main. `parse spec` is the one that needs it: a json error quotes the
		// spec text it choked on, and the spec carries this process's config
		// values, a declared `Secret[T]` among them.
		fmt.Fprintln(os.Stderr, bridge.ScrubText("read spec: "+err.Error()))
		os.Exit(1)
	}
	var s spec
	if err := json.Unmarshal(raw, &s); err != nil {
		fmt.Fprintln(os.Stderr, bridge.ScrubText("parse spec: "+err.Error()))
		os.Exit(1)
	}
	if s.Name != "" {
		name = s.Name
	}
	// the proof lines' prefix: `[name#token]` when the runner sent a token,
	// which it rewrites to `[name]` for people (issue #1621)
	proofName := name
	if s.ProofOnStdin {
		proofName = name + "#" + readProofToken()
	}
	log := func(channel, subject, detail string) {
		// item 421 F5 — the runner's single log choke point. Probe results,
		// probe failures and load failures are formatted here from values the
		// runtime holds, and none of them passes through the in-process funnels
		// (the emitted hostRecord scrub covers the trace, not this line) or the
		// seam funnel (a probe dispatches in-process, so SeamFailure never runs).
		// Scrubbing the WHOLE rendered line -- channel, subject and detail --
		// covers the channel instead of each printer, and is the identity for a
		// marking-free placement, which installs no scrub. The banner lines
		// (`UP`, `DOWN`, `NO-RESIDUE`, the E-Stop inventory) are deliberately not
		// scrubbed: they are conductor protocol carrying only the spec's process
		// name, and mangling one would desynchronise the conductor.
		fmt.Println(bridge.ScrubText(fmt.Sprintf("[%s] %-6s| %-16s| %s", name,
			channel, subject, strings.TrimRight(detail, " "))))
	}

	// item 443 / issue #122: publish the spec latch to the ambient variable the
	// crossing seams (`bridge.Client.Call`, `bridge.serveConn`) and the idle
	// watcher below all read. Done BEFORE any proxy dials or any key is served,
	// so a latch already armed at boot is honored from the first crossing. A
	// placement that was never armed carries no latch and this is a no-op, so an
	// unarmed run is byte-identical to the pre-443 runner.
	if s.EstopLatch != "" {
		os.Setenv(estop.LatchEnv, s.EstopLatch)
	}

	root := stc.New()
	var fibers []labeledFiber
	var clients []*bridge.Client
	peer := make(chan string, 8)
	ready := stdctx.Background()

	// 1. proxies for keys provided by other processes (generated per service)
	for key, info := range s.Proxies {
		client, err := bridge.NewClient(info.Socket)
		if err != nil {
			// issue #2254: a proxy that cannot be reached leaves the
			// composition short, in both modes, as the rust runner's proxy
			// unwrap does. The fault sweep never targets a proxy, so `--once`
			// gets no exception: a dead provider must not read as NO-RESIDUE.
			fatalBoot(name, "proxy dial failed for key "+key+": "+err.Error(), fibers, log)
		}
		clients = append(clients, client)
		comp, ok := emitted.RevlProxyComponent(key, info.Service, client)
		if !ok {
			// issue #2254: a proxy this build has no component for is the
			// same spec/build mismatch as an unknown component (#2223).
			fatalBoot(name, "unsupported proxy service "+info.Service+" for key "+
				key+": the spec names a proxy this build does not have", fibers, log)
		}
		fiber := root.Load(comp)
		if err := fiber.Ready(ready); err != nil {
			// issue #2254: fatal in both modes, as for a failed dial above.
			fatalBoot(name, "boot failed loading proxy for key "+key+": "+err.Error(), fibers, log)
		}
		fibers = append(fibers, labeledFiber{key + "-proxy", fiber})
		log("proxy", key, "-> "+info.Socket+" ["+info.Service+"]")
		k := key
		bridge.Monitor(info.Socket, func() { peer <- k })
	}

	// 2. this process's own components, in IR load order
	for _, cname := range s.Components {
		fiber, ok := emitted.RevlLoad(root, cname, s.Config)
		if !ok {
			// issue #2223: a component the generated registry does not have
			// is a FATAL spec/build mismatch, as in the rust runner (#2200).
			// Logging past it left the placement short of the composition it
			// claims: UP, NO-RESIDUE and exit 0 with that component never
			// loaded. Dispose what did boot, last first, print one scrubbed
			// line on stderr and exit 1. `os.Exit`, not a panic or a return,
			// so the teardown below never prints `DOWN` for a failed boot.
			fatalBoot(name, "unknown component "+cname+": the spec names a "+
				"component this build does not have", fibers, log)
		}
		if err := fiber.Ready(ready); err != nil {
			// issue #2254: outside `--once` a failed activation is fatal, as
			// in the rust runner. In `--once` mode the FAILED fiber is kept so
			// the LIFO teardown and the no-residue proof the fault sweep reads
			// still run; stc has already unwound its own effects.
			if !s.Once {
				fatalBoot(name, "boot failed loading "+cname+": "+err.Error(), fibers, log)
			}
			log("load", cname, "load error: "+err.Error())
		}
		fibers = append(fibers, labeledFiber{cname, fiber})
		log("load", cname, "state="+fiber.State().String())
	}

	// 3. serve the keys other processes need
	var listener net.Listener
	if s.Serve != nil && s.Serve.Socket != "" {
		os.Remove(s.Serve.Socket)
		ln, err := net.Listen("unix", s.Serve.Socket)
		if err != nil {
			log("serve", strings.Join(s.Serve.Keys, ", "), "listen error: "+err.Error())
		} else {
			listener = ln
			surface := newExportedSurface(s.Serve)
			go bridge.Serve(ln, func(key, method string, args []json.RawMessage) (any, error) {
				// No `guard` here (issue #2481): `bridge.Serve` recovers a
				// panic raised in a provider method into this crossing's error
				// reply, scrubbed by `bridge.SeamFailure` like any returned
				// error, and keeps serving, as the py, ts and java runners do.
				// A guard deferred here would run first and halt the process.
				if err := surface.check(key, method, sortedOps(s.Serve.Methods[key])); err != nil {
					return nil, err
				}
				return invokeIn(root, s.Placements, key, method, args)
			})
			log("serve", strings.Join(s.Serve.Keys, ", "), "-> "+s.Serve.Socket)
		}
	}

	// 4. probes: call provided services (may cross a seam), print results
	for _, pr := range s.Probe {
		args := pr.Args
		label := pr.Key + "." + pr.Method + "(...)"
		value, err := invokeIn(root, s.Placements, pr.Key, pr.Method, args)
		if err != nil {
			log("probe", label, "ERROR "+err.Error())
			continue
		}
		encoded, _ := json.Marshal(value)
		log("probe", label, "=> "+string(encoded))
	}

	// 5. THE STOP HANDLER GOES UP BEFORE THE `UP` LINE, and that ordering is
	//    the whole contract (the go half of the fix py got in #226; issue 290).
	//    `[name] UP` is what the conductor waits on: `run_placement`'s `--once`
	//    path blocks on every child's UP and then calls `stop_all` immediately,
	//    so the SIGTERM can land microseconds after the print. Printing first
	//    left a window in which go's DEFAULT SIGTERM disposition was still in
	//    force, and a signal arriving inside it killed this process outright —
	//    no LIFO unwind, no inverses replayed, no residue proof, no `DOWN` (G7
	//    and R4, both violated). The window belongs to the LAST process to boot
	//    — every earlier one is still being waited on — which is why it lands
	//    on the process most likely to still owe an inverse and a residue proof.
	//
	//    The restructure the reorder needed: `signal.Notify` cannot simply move
	//    up on its own, because the channels it feeds are consumed by the
	//    `select` below, which must stay AFTER the print (it blocks). So the
	//    whole rendezvous — `stop`, `sig`, and the two feeder goroutines — is
	//    hoisted here, and only the blocking `select` is left behind. Both
	//    channels are buffered (cap 1), so a signal arriving in the old window
	//    is now merely PARKED in `stop` and the `select` below returns from it
	//    at once: the unwind runs either way, and `UP` means what it says —
	//    loaded, serving, AND able to be stopped.
	//
	//    Installed in once mode too, where there is no `select` to reach it: a
	//    SIGTERM landing during the immediate once-mode teardown is absorbed
	//    rather than turned back into a kill of a half-finished unwind.
	stop := make(chan struct{}, 1)
	sig := make(chan os.Signal, 1)
	signal.Notify(sig, syscall.SIGTERM, syscall.SIGINT)
	go func() { <-sig; stop <- struct{}{} }()
	go func() { io.Copy(io.Discard, os.Stdin); stop <- struct{}{} }()

	fmt.Printf("[%s] UP\n", proofName)

	// 5a. item 443 / issue #122 — the idle watcher. The seams refuse lazily, at
	//     the NEXT crossing, which is useless for a process parked in the select
	//     below waiting to be stopped: it crosses nothing and would sit through
	//     the emergency. So the runner polls the latch and, on the button, prints
	//     its in-flight inventory on one `[name] HALTED {json}` line (the
	//     conductor merges it by prefix — `src/revl/placement.py::pump` — with no
	//     second channel) and calls `os.Exit`, which runs NO teardown: no LIFO
	//     unwind, no inverse, no no-residue proof, no `DOWN`. That is the whole
	//     point of the halt (docs/design/443-estop.md). The go twin of the py
	//     runner's `estop_from_latch` and the ts runner's `haltOnLatch`. Started
	//     only when the placement is armed, so an unarmed run spawns no watcher.
	if s.EstopLatch != "" {
		go func() {
			// The watcher's own funnel: it reads and parses the latch file and
			// composes the HALTED inventory on a goroutine main's defer cannot
			// see.
			defer guard(&name)()
			for {
				if record := estop.ReadLatch(estop.LatchPath("", "", true)); record != nil {
					fmt.Println(estop.EstopHaltLine(name, estop.InFlightCrossings(), record))
					os.Stdout.Sync()
					os.Exit(0)
				}
				time.Sleep(20 * time.Millisecond)
			}
		}()
	}

	// 5b. once mode: the round-trip ends here — boot, then straight to LIFO
	//     teardown + the no-residue proof. Otherwise hold until the conductor
	//     stops us (SIGTERM, or stdin EOF) OR a peer dies. A dead provider
	//     withdraws its proxy so consumers deactivate.
	if !s.Once {
		select {
		case key := <-peer:
			log("peer", key, "provider died: withdrawing the proxy")
			for _, lf := range fibers {
				if lf.label == key+"-proxy" {
					lf.fiber.Dispose()
				}
			}
			// Observe dependents leave Active: the provision is withdrawn, so the
			// orchestrator deactivates every consumer of the lost key (R2/R3).
			deadline := time.Now().Add(3 * time.Second)
			for _, lf := range fibers {
				if strings.HasSuffix(lf.label, "-proxy") {
					continue
				}
				for time.Now().Before(deadline) && lf.fiber.State() == stc.StateActive {
					time.Sleep(20 * time.Millisecond)
				}
				log("withdraw", lf.label, "state="+lf.fiber.State().String())
			}
		case <-stop:
		}
	}

	// 6. teardown, consumers first (reverse load order). Each dispose is
	//    awaited (bounded) in both modes: the inverses of a held composition
	//    must replay before `DOWN`, and in once mode the residue proof below
	//    reads a settled runtime, not an in-flight one.
	goneCtx, cancel := stdctx.WithTimeout(stdctx.Background(), teardownBound())
	defer cancel()
	var unconfirmed []string
	for i := len(fibers) - 1; i >= 0; i-- {
		if !disposeAwaited(goneCtx, fibers[i], log) {
			unconfirmed = append(unconfirmed, fibers[i].label)
		}
	}
	if listener != nil {
		listener.Close()
	}
	for _, c := range clients {
		c.Close()
	}
	// A dispose that did not settle may still have inverses pending, so this
	// is not a finished unwind: no residue verdict and no `DOWN` (the
	// conductor reads `DOWN` as proof the LIFO unwind completed), one scrubbed
	// FATAL line naming the fibers, and a non-zero exit. `os.Exit` skips the
	// deferred `cancel`, which is harmless at process end (issue #2339).
	if len(unconfirmed) > 0 {
		fatalLine(name, "teardown incomplete: dispose not confirmed before the bound expired for "+
			strings.Join(unconfirmed, ", "))
		os.Exit(1)
	}

	// 7. no-residue proof (once mode): after a full LIFO teardown the live
	//    runtime must hold nothing — no fiber left in the registry, and no
	//    provided key still resolving. The go mirror of the py driver's
	//    registry.size/reflect.store check and the rust runner's
	//    registry().len()/reflect().services() check; NO-RESIDUE is printed
	//    only when both hold.
	if s.Once {
		live := len(root.Fibers())
		log("residue", "plugins", fmt.Sprintf("%d live plugin(s)", live))
		still := 0
		for _, key := range s.Provides {
			if emitted.RevlStillProvided(root, key) {
				still++
				log("residue", key, "STILL LIVE")
			}
		}
		log("residue", "provisions", fmt.Sprintf("%d service(s) still provided", still))
		if live == 0 && still == 0 {
			fmt.Printf("[%s] NO-RESIDUE — the composition left nothing behind\n", proofName)
		} else {
			fmt.Printf("[%s] RESIDUE-LEFT — see the residue lines above\n", proofName)
		}
	}
	fmt.Printf("[%s] DOWN\n", proofName)
}

// invokeIn dispatches a served or probed call against the provision `key`
// resolves to, in the py tier's `resolve_key` order (issue #1567): the shared
// realm when the key is provided there (or this process does not provide it at
// all: a proxy), else its one isolated realm. A key isolated in two or more
// realms has no single provider for a call that names only the key, so it is
// refused naming each provider and realm.
func invokeIn(root *stc.Context, placements map[string][]placement, key, method string,
	args []json.RawMessage) (any, error) {
	at := placements[key]
	shared := len(at) == 0
	for _, p := range at {
		if p.Realm == nil {
			shared = true
		}
	}
	if shared {
		return emitted.RevlInvoke(root, key, method, args)
	}
	if len(at) == 1 {
		ctx, ok := emitted.RevlRealmContext(root, key, *at[0].Realm)
		if !ok {
			return nil, fmt.Errorf("key '%s' is provided in realm `%s` by `%s`, and this "+
				"runner has no context for that realm", key, *at[0].Realm, at[0].Component)
		}
		return emitted.RevlInvoke(ctx, key, method, args)
	}
	where := make([]string, len(at))
	for i, p := range at {
		where[i] = fmt.Sprintf("`%s` in realm `%s`", p.Component, *p.Realm)
	}
	return nil, fmt.Errorf("key '%s' is provided in %d realms (%s); a call names a key, "+
		"not a realm, so it has no single provider to reach", key, len(at), strings.Join(where, ", "))
}
